package com.ivonix.pulse.ontology.domain;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AviationService extends DomainDataService { public AviationService(JdbcTemplate j){super(j,"aviation_data",Set.of("altitude","airspeed","engine_vibration","flight_phase"));} public DomainDiagnosticResult diagnose(UUID d,UUID o){var x=latest(d,o,1);if(!x.isEmpty()){double v=number(x.get(0),"engine_vibration");if(!Double.isNaN(v)&&v>1.5)return new DomainDiagnosticResult("aviation","Engine vibration anomaly",.90,List.of("Follow approved inspection procedure","Review engine vibration trend"));}return new DomainDiagnosticResult("aviation","No immediate rule-based fault",.10,List.of("Continue approved monitoring"));}}